					title: '处理中...'
				});
				// 如果已经下载本地路径，那么直接储存
				let obj = {
					filePath: url,
					success: () => {
						uni.showModal({
							content: '处理成功',
							showCancel: false
						});
						uni.hideLoading();
					},
					fail: e => {
						uni.hideLoading();
						uni.showModal({
